function Intersperse(numbers: array of integer; delimeter: integer): array of integer;
begin
  if numbers.Length = 0 then
  begin
    Result := new integer[0];
    exit;
  end;
  var res := new integer[numbers.Length * 2 - 1];
  for var i := 0 to numbers.Length - 1 do
  begin
    res[i * 2] := numbers[i];
    if i < numbers.Length - 1 then
      res[i * 2 + 1] := delimeter;
  end;
  Result := res;
end;


function ParseNestedParens(parenString: string): array of integer;
begin
  var maxDepth := 0;
  var currentDepth := 0;
  var maxDepthStack := new Stack<integer>;
  var maxDepthStackIndex := new Stack<integer>;
  var resultList := new List<integer>;
  var index := 0;

  while index < parenString.Length do
  begin
    if parenString[index] = '(' then
    begin
      currentDepth += 1;
      maxDepthStack.Push(maxDepth);
      maxDepthStackIndex.Push(resultList.Count);
      resultList.Add(0);
    end
    else if parenString[index] = ')' then
    begin
      currentDepth -= 1;
      var maxDepthValue := maxDepthStack.Pop;
      var maxDepthIndex := maxDepthStackIndex.Pop;
      resultList[maxDepthIndex] += 1;
      if maxDepthValue + 1 > resultList[maxDepthIndex] then
        resultList[maxDepthIndex] := maxDepthValue + 1;
    end;
    index += 1;
  end;

  Result := resultList.ToArray;
end;


