function LargestDivisor(n: integer): integer;
begin
  var i := n - 1;
  while i >= 1 do
  begin
    if n mod i = 0 then
    begin
      Result := i;
      exit;
    end;
    i := i - 1;
  end;
  Result := 1;
end;


function Factorize(n: integer): array of integer;
begin
  var factors := new List<integer>;
  var i := 2;
  while i * i <= n do
  begin
    if n mod i = 0 then
    begin
      n := n div i;
      factors.Add(i);
    end
    else
      i += 1;
  end;
  if n > 1 then
    factors.Add(n);
  Result := factors.ToArray;
end;


