function ChangeBase(x: integer; base: integer): string;
begin
  if (x = 0) or (base < 2) then
  begin
    Result := '';
    exit;
  end;
  var digits := '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ';
  var res := '';
  while x > 0 do
  begin
    res := digits[x mod base] + res;
    x := x div base;
  end;
  Result := res;
end;


