function Monotonic(l: array of integer): boolean;
begin
  if l.Length = 0 then
  begin
    Result := True;
    exit;
  end;

  var increasing := True;
  var decreasing := True;

  for var i := 1 to l.Length - 1 do
  begin
    if l[i] < l[i - 1] then
      increasing := False;

    if l[i] > l[i - 1] then
      decreasing := False;
  end;

  Result := increasing or decreasing;
end;


