  for var i := 0 to arr.Length - 1 do
  begin
    if (arr[i] mod 2 = 0) and (arr[i] <> smallestEven) then
    begin
      evenList.Add(arr[i]);
      evenIndex.Add(i);
      smallestEven := arr[i];
    end;
  end;

  if evenList.Count > 0 then
  begin
    for var i := 0 to evenList.Count - 1 do
    begin
      if evenList[i] <= smallestEven then
      begin
        smallestEven := evenList[i];
        smallestIndex := evenIndex[i];
      end;
    end;
    Result := new integer[2] of smallestEven, smallestIndex;
  end
  else
    Result := new integer[0];
end;


