function SmallestChange(arr: array of integer): integer;
begin
  var n := arr.Length;
  var dp := new integer[n + 1, n + 1];
  for var i := 0 to n do
    dp[i, i] := 0;
  for var i := 0 to n - 1 do
    if arr[i] = arr[i + 1] then
      dp[i, i + 1] := 0
    else
      dp[i, i + 1] := 1;
  for var l := 2 to n do
    for var i := 0 to n - l do
    begin
      var j := i + l;
      if arr[i] = arr[j] then
        dp[i, j] := dp[i + 1, j - 1]
      else
        dp[i, j] := Min(dp[i + 1, j], dp[i, j - 1]) + 1;
    end;
  Result := dp[0, n - 1];
end;


