function Multiply(a, b: integer): integer;
begin
  var product := 0;
  var aDigit := 0;
  var bDigit := 0;
  var aNum := a;
  var bNum := b;
  var aDigitCount := 0;
  var bDigitCount := 0;

  while aNum > 0 do
  begin
    aDigit := aNum mod 10;
    aDigitCount += 1;
    aNum := aNum div 10;
  end;

  while bNum > 0 do
  begin
    bDigit := bNum mod 10;
    bDigitCount += 1;
    bNum := bNum div 10;
  end;

  for var i := 1 to aDigitCount do
    product := product + aDigit;

  for var i := 1 to bDigitCount do
    product := product + bDigit;

  Result := product;
end;


