  for var i := 0 to n - 1 do
    for var j := 0 to m - 1 do
      if grid[i, j] = 1 then
        buckets[i, j] := 1;

  while true do
  begin
    var filled := 0;
    var empty := 0;
    var toEmpty := new List<(integer, integer)>;

    for var i := 0 to n - 1 do
      for var j := 0 to m - 1 do
        if buckets[i, j] = 1 then
        begin
          filled += 1;
          if (i < n - 1) and (grid[i + 1, j] = 0) then
            toEmpty.Add((i + 1, j));
          if (j < m - 1) and (grid[i, j + 1] = 0) then
            toEmpty.Add((i, j + 1));
        end
        else
          empty += 1;

    if filled = 0 then
    begin
      Result := res;
      exit;
    end;

    foreach var (i, j) in toEmpty do
    begin
      buckets[i, j] := 0;
      if buckets[i, j] = 1 then
        empty += 1;
    end;

    res += 1;
    if empty >= capacity then
    begin
      res += (empty - capacity) div capacity;
      empty := capacity;
    end;
  end;
end;


