function Minpath(grid: array of array of integer; k: integer): array of integer;
begin
  var n := grid.Length;
  var directions := new List<(integer, integer)>;
  directions.Add((-1, 0));
  directions.Add((1, 0));
  directions.Add((0, -1));
  directions.Add((0, 1));

  var visited := new HashSet<(integer, integer)>;
  var queue := new Queue<(integer, integer, integer)>;
  queue.Enqueue((grid[0, 0], 0, 0));
  visited.Add((0, 0));

  while queue.Count > 0 do
  begin
    var (val, x, y) := queue.Dequeue;
    if k = 0 then
    begin
      Result := new integer[1] of val;
      exit;
    end;

    for var i := 0 to directions.Count - 1 do
    begin
      var (dx, dy) := directions[i];
      var nx := x + dx;
      var ny := y + dy;
      if (nx >= 0) and (nx < n) and (ny >= 0) and (ny < n) and
         not visited.Contains((nx, ny)) then
      begin
        queue.Enqueue((grid[nx, ny], nx, ny))
      end;
    end;
    visited.Add((x, y));
  end;

  Result := new integer[0];
end;


