        res.Add(ch.ToLower)
      else
        res.Add(ch.ToUpper);
    end
    else if Char.IsDigit(ch) then
      res.Add(digits[StrToInt(ch.ToString)])
    else
      res.Add(specials[specials.Count - 1]);
    specials.RemoveAt(specials.Count - 1);
  end;
  if res.Count = 0 then
    res.AddRange(specials);
  Result := string.Join('', res);
end;


function StringToMd5(text: string): string;
begin
  if text = '' then
  begin
    Result := '';
    exit;
  end;
  var h := new System.Security.Cryptography.MD5CryptoServiceProvider;
  var b := h.ComputeHash(System.Text.Encoding.UTF8.GetBytes(text));
  Result := System.Convert.ToBase64String(b);
end;


function GenerateIntegers(a, b: integer): array of integer;
begin
  var res := new List<integer>;
  for var i := a to b do
    if i mod 2 = 0 then
      res.Add(i);
  Result := res.ToArray;
end;
